  "problem-023": "function solve(text) {\n  const cleaned = text.trim();\n  if (cleaned === '') {\n    return 0;\n  }\n  const words = cleaned.split(' ');\n  let count = 0;\n  for (const word of words) {\n    count += 1;\n  }\n  return count;\n}\n\nconst example = \"one   two\\nthree\";\nconsole.log(await solve(example));",
  "problem-024": "function solve(title) {\n  const trimmed = title.trim();\n  if (!trimmed) {\n    return '';\n  }\n  const words = trimmed.toLowerCase().split(/\\s+/);\n  const parts = [];\n  for (const word of words) {\n    parts.push(word);\n  }\n  // TODO: join the parts with hyphens and return the slug.\n}\n\nconst example = \"  Learn  JavaScript \";\nconsole.log(await solve(example));",
  "problem-025": "function solve(text) {\n  const cleaned = text.toLowerCase().replace(/\\s/g, '');\n  let left = 0;\n  let right = cleaned.length;\n  while (left < right) {\n    if (cleaned[left] !== cleaned[right]) {\n      return false;\n    }\n    left += 1;\n    right -= 1;\n  }\n  return true;\n}\n\nconst example = \"Never odd or even\";\nconsole.log(await solve(example));",
  "problem-026": "function solve(words) {\n  let longest = '';\n  let longestLength = 0;\n  for (const word of words) {\n    const length = word.length;\n    if (length >= longestLength) {\n      longest = word;\n      longestLength = length;\n    }\n  }\n  return longest;\n}\n\nconst example = [\n  \"cat\",\n  \"dog\"\n];\nconsole.log(await solve(example));",
